  private static string _t(string key, string locale, Dictionary<string, object> vars) {
    string loc = locale ?? _DEFAULT_LOCALE;
    Dictionary<string, string> table = null;
    if (!STRINGS.TryGetValue(loc, out table)) {
      string baseLoc = loc.Split('-')[0];
      if (!STRINGS.TryGetValue(baseLoc, out table)) {
        STRINGS.TryGetValue(_DEFAULT_LOCALE, out table);
      }
    }
    if (table == null || !table.TryGetValue(key, out string template)) {
      return key;
    }
    string result = template;
    foreach (KeyValuePair<string, object> kv in vars) {
      result = result.Replace("{" + kv.Key + "}", NewrRt.ToStr(kv.Value));
    }
    return result;
